class T:
    def __init__(s, v, l=None, r=None):
        s.v, s.left, s.right = v, l, r

def f(n, is_left=False):
    if not n:
        return 0
    if not n.left and not n.right:
        return n.v if is_left else 0
    return f(n.left, True) + f(n.right, False)

root = T(3, T(9), T(20, T(15), T(7)))
print(f(root))

bool isBST(Node* n) {
    if (!n) return true;
    if (n->left && n->left->val >= n->val) return false;
    if (n->right && n->right->val <= n->val) return false;
    return isBST(n->left) && isBST(n->right);
}

