from collections import deque

def level_sums(root):
    res, q = [], deque([root])
    while q:
        s = 0
        for _ in range(len(q)):
            n = q.popleft()
            s += n.v
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        res.append(s)
    return res

root = T(3, T(9), T(20, T(15), T(7)))
print(level_sums(root))

struct Node { int v; Node *l = nullptr, *r = nullptr; Node(int x) : v(x) {} };
void ins(Node*& n, int x) {
    if (!n) n = new Node(x);
    else if (x < n->v) ins(n->l, x);
    else ins(n->r, x);
}
void pre(Node* n) {
    if (!n) return;
    std::cout << n->v << ' ';
    pre(n->l);
    pre(n->r);
}
